package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import jakarta.servlet.Filter;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import static org.mockito.Mockito.*;import org.springframework.context.annotation.*;import org.springframework.core.env.MapPropertySource;import org.springframework.mock.web.MockServletContext;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.MeterRegistry;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class GitHubEvidenceSecurityTest {
 @Configuration(proxyBeanMethods=false) @EnableWebMvc @EnableWebSecurity @Import({SecurityConfiguration.class,RoadmapController.class,GitHubEvidenceController.class,GitHubEvidenceRelatedController.class,EvidenceSessionController.class,RoadmapErrors.class})
 static class Web {@Bean RoadmapStore roots(){return mock(RoadmapStore.class);}@Bean GitHubEvidenceStore store(){return mock(GitHubEvidenceStore.class);}@Bean EvidenceSessionStore sessions(){return mock(EvidenceSessionStore.class);}@Bean GitHubReferenceClient remote(){return mock(GitHubReferenceClient.class);}@Bean SpaceAuthorizationClient authority(){return mock(SpaceAuthorizationClient.class);}@Bean MeterRegistry metrics(){return new SimpleMeterRegistry();}}
 AnnotationConfigWebApplicationContext context;MockMvc mvc;GitHubEvidenceStore store;SpaceAuthorizationClient authority;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space=ids.next(),root=ids.next(),item=ids.next(),actor=ids.next();String token="a".repeat(43),path="/api/spaces/"+space+"/roadmaps/"+root+"/github-evidence";
 void start(boolean enabled){if(context!=null)context.close();context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("github-learning-security",Map.of("brain.learning.api.enabled",Boolean.toString(enabled),"brain.learning.browser-origin","https://localhost:8443")));context.register(Web.class);context.refresh();store=context.getBean(GitHubEvidenceStore.class);authority=context.getBean(SpaceAuthorizationClient.class);mvc=MockMvcBuilders.webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",Filter.class)).build();when(authority.authorize(eq(space),eq(token),anyBoolean(),anyString())).thenReturn(actor);when(authority.authorize(eq(space),eq(token),anyString(),eq("PRIVATE"),anyString())).thenReturn(actor);}
 @AfterEach void close(){if(context!=null)context.close();}
 @Test void enabledCatalogUsesBothLiveAuthoritiesAndRevocationStopsStore()throws Exception{start(true);when(store.page(space,root,"ACTIVE",null,20)).thenReturn(new GitHubEvidenceStore.Page<>(List.of(),null));mvc.perform(get(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));when(authority.authorize(eq(space),eq(token),eq("GITHUB_EVIDENCE_READ"),eq("PRIVATE"),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));mvc.perform(get(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isForbidden());verify(store).page(space,root,"ACTIVE",null,20);verifyNoMoreInteractions(store);}
 @Test void disabledAndUnsupportedPathsStayBlockedButAllNewWritersReachStrictGuards()throws Exception{start(false);mvc.perform(get(path).secure(true)).andExpect(status().isForbidden());verifyNoInteractions(store,authority);start(true);var cookie=new Cookie("__Host-brain_guest",token);mvc.perform(post(path).secure(true).cookie(cookie).header("Origin","https://localhost:8443").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(put(path+"/"+item).secure(true).cookie(cookie).header("Origin","https://localhost:8443").contentType("application/json").content("{}")).andExpect(status().isPreconditionRequired());mvc.perform(delete(path+"/"+item).secure(true).cookie(cookie).header("Origin","https://localhost:8443")).andExpect(status().isPreconditionRequired());mvc.perform(put(path+"/"+item+"/study-session").secure(true).cookie(cookie).header("Origin","https://localhost:8443").contentType("application/json").content("{}")).andExpect(status().isPreconditionRequired());mvc.perform(get(path+"/"+item+"/extra").secure(true).cookie(cookie)).andExpect(status().isForbidden());verifyNoInteractions(store);}
 @Test void relatedReadIsScopedAndSessionHistoryUsesRestrictedAuthority()throws Exception{start(true);var cookie=new Cookie("__Host-brain_guest",token);when(store.related(space,root,item,"ACTIVE",null,20)).thenReturn(new GitHubEvidenceStore.Page<>(List.of(),null));mvc.perform(get("/api/spaces/"+space+"/github-learning-evidence").secure(true).cookie(cookie).param("repositoryId",root.toString()).param("commitId",item.toString())).andExpect(status().isOk());when(context.getBean(EvidenceSessionStore.class).history(space,root,item,"GITHUB",Long.MAX_VALUE,5)).thenReturn(List.of());mvc.perform(get(path+"/"+item+"/study-session/revisions").secure(true).cookie(cookie)).andExpect(status().isOk());verify(authority,times(2)).authorize(eq(space),eq(token),eq("GITHUB_EVIDENCE_READ"),eq("PRIVATE"),anyString());}
}
